	@Test
	void estimateJustifiedCorrelatedOptionalIsServedByOneSweep() {
		List<String> expected = rows(QUERY);
		assertThat(expected).hasSize(180 * 2 + 2 + 20); // 360 matched + outer0's second seed fan-out + 20 bare

		System.setProperty(SWEEP_FLAG, "true");
		long sweepsBefore = LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get();
		long memoBefore = LmdbNativeAggregateCompiler.LEFTJOIN_MEMO_MATERIALIZATIONS.get();
		List<String> actual = rows(QUERY);

		assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(LmdbNativeAggregateCompiler.LEFTJOIN_SWEEP_BUILDS.get() - sweepsBefore)
				.as("the fragment must be swept exactly once for the whole outer stream")
				.isOne();
		assertThat(LmdbNativeAggregateCompiler.LEFTJOIN_MEMO_MATERIALIZATIONS.get() - memoBefore)
				.as("no per-key fragment materializations once the sweep answers every probe")
				.isZero();
	}

